SOURCE=''
from pathlib import Path
import base64,hashlib,json,os,platform,resource,select,subprocess,time
work=Path.home()/"root-managed-notify-bafc-v1"
work.mkdir(mode=0o700)
source=base64.b64decode(SOURCE)
assert hashlib.sha256(source).hexdigest()=="bafc3ff31ae9f5a4c484124911c890494860bc88c50fd2d751aed57c2f44aab7"
(work/"fixture.rs").write_bytes(source)
manifest='[package]\nname="managed-memory-notify-fixture"\nversion="0.0.0"\nedition="2024"\n[[bin]]\nname="managed-memory-notify-fixture"\npath="fixture.rs"\n[dependencies]\nlibc="=0.2.189"\n'
(work/"Cargo.toml").write_text(manifest)
cores=os.sched_getaffinity(0);os.sched_setaffinity(0,{min(cores)})
resource.setrlimit(resource.RLIMIT_AS,(1024**3,1024**3))
resource.setrlimit(resource.RLIMIT_FSIZE,(2*1024**3,2*1024**3))
env=dict(os.environ,CARGO_BUILD_JOBS="1",CARGO_TARGET_DIR=str(work/"target"))
for k in ("RUSTFLAGS","CARGO_ENCODED_RUSTFLAGS","RUSTC_WRAPPER","RUSTC_WORKSPACE_WRAPPER"):
 env.pop(k,None)
def command(name,args,timeout=120):
 (work/(name+".command.json")).write_text(json.dumps(args))
 with (work/(name+".log")).open("wb") as out:
  r=subprocess.run(args,cwd=work,env=env,stdout=out,stderr=subprocess.STDOUT,timeout=timeout)
 (work/(name+".exit")).write_text(str(r.returncode)+"\n")
 if r.returncode:raise RuntimeError(name+" failed:"+str(r.returncode))
command("rustc",["rustc","--version","--verbose"])
command("cargo",["cargo","--version"])
(work/"host.json").write_text(json.dumps({"uname":list(platform.uname()),"affinity":list(os.sched_getaffinity(0)),"filesystem":list(os.statvfs(work)),"policy_sha256":"d634fcb944959ce1e40a9277d12b0905fcfcebf82d9da9832e826f790a349242","role":"ROOT coordinator native regularfile framing only; not pressure/OOM or VM proof"},indent=2))
command("lock",["cargo","generate-lockfile","--offline"])
lock=(work/"Cargo.lock").read_text();assert '3eaf3ede3fee6db1a4c2ee091bf8a8b4dccdc6d17f656fb07896ee72867612f2' in lock
command("compile",["cargo","build","--offline","--locked","--release","-j1"])
binary=work/"target/release/managed-memory-notify-fixture"
(work/"binary.sha256").write_text(hashlib.sha256(binary.read_bytes()).hexdigest()+"\n")
results=[]
for name,writes,envelope,expected in [("header",1,16,0),("header-plus-one",3,17,0),("existing",1,17,1),("expired",1,17,1)]:
 case=work/name;case.mkdir(mode=0o700)
 path=case/"owned-artifact"
 sentinel=None
 if name=="existing":
  path.mkdir();(path/"sentinel").write_bytes(b"owned-existing-preserve");sentinel=hashlib.sha256((path/"sentinel").read_bytes()).hexdigest()
 deadline=time.clock_gettime_ns(time.CLOCK_MONOTONIC)+(30_000_000_000 if name!="expired" else -1)
 argv=[str(binary),str(path),str(deadline),str(writes),str(envelope)]
 before=len(list(Path("/proc/self/fd").iterdir()))
 with (case/"stdout").open("wb") as out,(case/"stderr").open("wb") as err:
  child=subprocess.Popen(argv,env=env,stdout=out,stderr=err)
  pidfd=os.pidfd_open(child.pid,0)
  try:
   rc=child.wait(timeout=45);ready=bool(select.select([pidfd],[],[],0)[0])
  finally:os.close(pidfd)
 after=len(list(Path("/proc/self/fd").iterdir()))
 text=(case/"stdout").read_text();errtext=(case/"stderr").read_text()
 record={"name":name,"argv":argv,"exit":rc,"expected":expected,"held_child_exit_ready":ready,"parent_fds_before":before,"parent_fds_after":after,"child_kernel_charge_return":"UNVERIFIED; not inferred from parent FD count or exit"}
 if name=="existing":record["sentinel_unchanged"]=hashlib.sha256((path/"sentinel").read_bytes()).hexdigest()==sentinel
 if name=="expired":record["no_new_path"]=not path.exists()
 if expected==0:
  record["independent_final_readback"]=(path/"watched").read_bytes()==b"\x01"*writes
  record["observed_drain_eagain"]="drained_witness=EAGAIN" in text
  record["actual_closes"]="close_notify" in text and "close_writer" in text
 results.append(record);(case/"result.json").write_text(json.dumps(record,indent=2)+"\n")
 assert rc==expected and ready and before==after,record
 if expected==0:assert all(record[x] for x in ("independent_final_readback","observed_drain_eagain","actual_closes")),record
 if name=="existing":assert record["sentinel_unchanged"]
 if name=="expired":assert record["no_new_path"]
(work/"results.json").write_text(json.dumps(results,indent=2)+"\n")
print(json.dumps({"records":str(work),"results":results}))
